-- Most quest points are used only while that objective is active. Keep the
-- position tables compact and expand the relevant, shared sets on demand.
local cache = setmetatable({}, {__mode='v'})
local pointCache = setmetatable({}, {__mode='v'})
local keys = {}
local deferred = {__index=function(row, key)
 local setID = row[keys][key]
 if not setID then return nil end
 local places = cache[setID]
 if places then return places end
 places = {}
 for index,id in ipairs(setData[setID]) do
  local point = pointCache[id]
  if not point then
   local m,x,y,n,z,i,o = unpack(pointData[id], 1, 7)
   point = {mapID=m,x=x,y=y,name=n,zone=z,npcID=i,objectID=o,sourceName=(i or o) and n or nil,source=source}
   pointCache[id] = point
  end
  places[index] = point
 end
 cache[setID] = places
 return places
end}
local function defer(row, places)
 row[keys] = places
 return setmetatable(row, deferred)
end
